<?php
require_once __DIR__.'/../config/config.php';$pdo=db();ensureAuthSchema($pdo);$token=(string)($_GET['token']??$_POST['token']??'');$s=$pdo->prepare("SELECT prt.*,u.id user_id FROM password_reset_tokens prt JOIN users u ON u.id=prt.user_id WHERE prt.token_hash=? AND prt.used_at IS NULL AND prt.expires_at>NOW() AND u.status='Active' LIMIT 1");$s->execute([hash('sha256',$token)]);$row=$s->fetch();$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$n=(string)($_POST['new_password']??'');$c=(string)($_POST['confirm_password']??'');if(!$row)$error='This reset link is invalid or expired.';elseif(strlen($n)<8)$error='Password must be at least 8 characters.';elseif($n!==$c)$error='Passwords do not match.';else{$pdo->prepare("UPDATE users SET password_hash=?,must_change_password=0,remember_token_hash=NULL,remember_token_expires_at=NULL WHERE id=?")->execute([password_hash($n,PASSWORD_DEFAULT),(int)$row['user_id']]);$pdo->prepare("UPDATE password_reset_tokens SET used_at=NOW() WHERE id=?")->execute([(int)$row['id']]);$success='Password reset successfully. You may now sign in.';}}
$bg=preg_replace('/[^a-z0-9-]/i','',strtolower(getSetting('login_background','philippine-blue')));?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reset Password | Procurement Data Monitoring</title><link rel="stylesheet" href="assets/style.css?v=20261008-login"></head><body class="login-page login-bg-<?=e($bg)?>"><div class="login-shell"><section class="login-visual"><div class="login-brand">PROCUREMENT DATA MONITORING<small>Procurement Planning and Monitoring System</small></div><div class="login-visual-content"><span class="login-kicker">ACCOUNT SECURITY</span><h2>Create a new password.</h2><p>Choose a password you will use for future sign-ins.</p></div></section><section class="login-form-panel"><div class="login-form-inner"><h1>Reset Password</h1><p class="login-subtitle">Choose a new password.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><a class="login-submit login-submit-link" href="login.php">Return to Login</a><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="token" value="<?=e($token)?>"><div class="login-field"><label>New Password</label><div class="login-input-wrap"><input type="password" name="new_password" minlength="8" required></div></div><div class="login-field"><label>Confirm New Password</label><div class="login-input-wrap"><input type="password" name="confirm_password" minlength="8" required></div></div><button class="login-submit" type="submit">Reset Password</button></form><?php endif;?></div></section></div></body></html>